#!/usr/bin/env node
// Copies the knowledge base (data/*.json, llms.txt, SKILL.md) from the repository
// root into a generated ES module so the Worker bundle is self-contained.
//
// Run it after editing anything under `data/`. `npm test` runs it first, and
// `test/assets.test.js` fails when the generated file is stale.

import { readFileSync, writeFileSync, statSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const workerDir = resolve(here, '..');
const repoDir = resolve(workerDir, '..');

/** Data files served at /data/:name and used by the four MCP tools. */
export const DATA_FILES = {
  compensation_plan: 'data/compensation_plan.json',
  health_nutrition: 'data/health_nutrition.json',
  beauty_skincare: 'data/beauty_skincare.json',
  home_living: 'data/home_living.json',
  faq_and_risks: 'data/faq_and_risks.json',
};

/** Documents served verbatim at the root of the Worker. */
export const DOC_FILES = {
  llmsTxt: 'llms.txt',
  skillMd: 'SKILL.md',
};

const OUT = join(workerDir, 'src', 'assets.generated.js');

function read(rel) {
  return readFileSync(join(repoDir, rel), 'utf8');
}

function sha256(text) {
  return createHash('sha256').update(text, 'utf8').digest('hex').slice(0, 16);
}

const data = {};
const digests = {};
for (const [name, rel] of Object.entries(DATA_FILES)) {
  const raw = read(rel);
  JSON.parse(raw); // fail loudly on broken JSON before it reaches a deploy
  data[name] = raw;
  digests[`data/${name}`] = sha256(raw);
}
const docs = {};
for (const [key, rel] of Object.entries(DOC_FILES)) {
  const raw = read(rel);
  docs[key] = raw;
  digests[rel] = sha256(raw);
}

const banner = `// AUTO-GENERATED by scripts/sync-data.mjs — do not edit by hand.
// Source: ../data/*.json, ../llms.txt, ../SKILL.md (repository root).
// Rebuild with: npm run sync-data
`;

const parts = [banner];
parts.push(`export const DATA_RAW = {\n${Object.entries(data)
  .map(([k, v]) => `  ${k}: ${JSON.stringify(v)},`)
  .join('\n')}\n};\n`);
parts.push(`export const DOCS_RAW = {\n${Object.entries(docs)
  .map(([k, v]) => `  ${k}: ${JSON.stringify(v)},`)
  .join('\n')}\n};\n`);
parts.push(`export const SOURCE_DIGEST = ${JSON.stringify(digests, null, 2)};\n`);

const next = parts.join('\n');
let current = '';
try {
  current = readFileSync(OUT, 'utf8');
} catch {
  current = '';
}
if (current === next) {
  console.log(`sync-data: up to date (${Object.keys(data).length} data files, ${Object.keys(docs).length} docs)`);
} else {
  writeFileSync(OUT, next, 'utf8');
  // The generated file is what the user will copy; report its size.
  console.log(
    `sync-data: wrote ${OUT.replace(repoDir + '/', '')} ` +
      `(${(statSync(OUT).size / 1024).toFixed(1)} KB)`,
  );
}
